;;
; @file   script_24.asm
; @brief   Farm visits by a neighbour in the early morning (fAreaEvents_Farm, arguments $0006 / $000B): slot 0
;         announces the festival of the next day (selected by nWeatherForecast $06-$0B: Flower, Harvest, Thanksgiving,
;         Star Night, New Year, Egg Festival), slots 1-3 are short greeting scenes (dialogs $047F, $0486, $0142).
; @bank   $B4   (AI byte code; script id $24, slot table generated by tools/ai/aidata.py from defs/ai/scripts.json)
; @see     script_26 script_27 script_28 docs/ai/commands.md
;;



    incsrc "../../../../build/gen/ai/slots_24.asm"
 
;;
; @brief   Slot 0: neighbour announces the festival of the next day, chosen by nWeatherForecast.
; @details Entry code: starts 1 child script (slots $02); dialogs $0272, $0240, $028E, $026E, $0289, $0274 (+1 more).
; @slot    0   (script slot index; AICMD0x09 / %AIExecute second argument)
; @callers fAreaEvents_Farm (A=$0006)
;;
pAIScripting0x24_Data01:
 
    %AICMD0x08_EnableAIControl()                               ;B4A475
    %AICMD0x1A($FFF8, $01A8, aAIScriptingData_L037, $02)                     ;B4A476
    %AICMD0x38_WaitForFadeIn()                                               ;B4A47E
    %AICMD0x3A_RunForTime(!AIINPUT_DOWN, 40)                   ;B4A47F
    %AICMD0x07_SetPlayerDirection(!PDIR_RIGHT)                 ;B4A483
    %AICMD0x1B($027B, $01)                                     ;B4A485
    %AICMD0x0D($01, $00, $80, $01)                             ;B4A489
    %AICMD0x13_Wait(30)                                        ;B4A48E
    %AICMD0x15_JumpIfEquals8(wram80(nWeatherForecast), 6, pAIScripting0x24_Data01_Announce_FlowerFestival)              ;B4A491
    %AICMD0x15_JumpIfEquals8(wram80(nWeatherForecast), 7, pAIScripting0x24_Data01_Announce_HarvestFestival)              ;B4A498
    %AICMD0x15_JumpIfEquals8(wram80(nWeatherForecast), 8, pAIScripting0x24_Data01_Announce_Thanksgiving)              ;B4A49F
    %AICMD0x15_JumpIfEquals8(wram80(nWeatherForecast), 9, pAIScripting0x24_Data01_Announce_StarNightFestival)              ;B4A4A6
    %AICMD0x15_JumpIfEquals8(wram80(nWeatherForecast), 10, pAIScripting0x24_Data01_Announce_NewYear)             ;B4A4AD
    %AICMD0x15_JumpIfEquals8(wram80(nWeatherForecast), 11, pAIScripting0x24_Data01_Announce_EggFestival)             ;B4A4B4
    %AICMD0x12_Jump(pAIScripting0x24_Data01_AnnounceEnd)                                   ;B4A4BB
; Festival announcement: dialog $0272 "It's the Flower Festival tomorrow. I'll stop...".
pAIScripting0x24_Data01_Announce_FlowerFestival:
    %AICMD0x1C_ShowDialog($0272, $00)                          ;B4A4BE
    %AICMD0x12_Jump(pAIScripting0x24_Data01_AnnounceEnd)                                   ;B4A4C2
; Festival announcement: dialog $0240 "The Harvest Festival is tomorrow.I'll stop w...".
pAIScripting0x24_Data01_Announce_HarvestFestival:
    %AICMD0x1C_ShowDialog($0240, $00)                          ;B4A4C5
    %AICMD0x12_Jump(pAIScripting0x24_Data01_AnnounceEnd)                                   ;B4A4C9
; Festival announcement: dialog $028E "It's the Thanksgiving Festival tomorrow. It'...".
pAIScripting0x24_Data01_Announce_Thanksgiving:
    %AICMD0x1C_ShowDialog($028E, $00)                          ;B4A4CC
    %AICMD0x12_Jump(pAIScripting0x24_Data01_AnnounceThanksgivingExtra)                                   ;B4A4D0
; Festival announcement: dialog $026E "It's the Star Night Festivaltomorrow. There...".
pAIScripting0x24_Data01_Announce_StarNightFestival:
    %AICMD0x1C_ShowDialog($026E, $00)                          ;B4A4D3
    %AICMD0x12_Jump(pAIScripting0x24_Data01_AnnounceEnd)                                   ;B4A4D7
; Festival announcement: dialog $0289 "It's the New Year's festivaltomorrow. You sh...".
pAIScripting0x24_Data01_Announce_NewYear:
    %AICMD0x1C_ShowDialog($0289, $00)                          ;B4A4DA
    %AICMD0x12_Jump(pAIScripting0x24_Data01_AnnounceEnd)                                   ;B4A4DE
; Festival announcement: dialog $0274 "It's Egg Festival tomorrow. I'll stop work e...".
pAIScripting0x24_Data01_Announce_EggFestival:
    %AICMD0x1C_ShowDialog($0274, $00)                          ;B4A4E1
    %AICMD0x12_Jump(pAIScripting0x24_Data01_AnnounceEnd)                                   ;B4A4E5
; Festival announcement.
pAIScripting0x24_Data01_AnnounceEnd:
    %AICMD0x13_Wait(30)                                        ;B4A4E8
    %AICMD0x1B($027B, $00)                                     ;B4A4EB
    %AICMD0x0D($FF, $00, $80, $01)                             ;B4A4EF
    %AICMD0x37()                                               ;B4A4F4
    %AICMD0x11_EnableUserControl()                             ;B4A4F5
    %AICMD0x10_End()                                           ;B4A4F6
; Festival announcement.
pAIScripting0x24_Data01_AnnounceThanksgivingExtra:
    %AICMD0x09_StartScript($02, pAIScripting0x24_Data01_Actor02)                                   ;B4A4F7
    %AICMD0x13_Wait(30)                                        ;B4A4FB
    %AICMD0x0C_WaitForScriptFlag($02)                                            ;B4A4FE
    %AICMD0x1B($027B, $00)                                     ;B4A500
    %AICMD0x0D($FF, $00, $80, $01)                             ;B4A504
    %AICMD0x37()                                               ;B4A509
    %AICMD0x11_EnableUserControl()                             ;B4A50A
    %AICMD0x10_End()                                           ;B4A50B
; Child script (slot $02) of Data01: actor. Spawns at (65528,424).
pAIScripting0x24_Data01_Actor02:
    %AICMD0x1A($FFF8, $01A8, aAIScriptingData_L033, $02)                     ;B4A50C
    %AICMD0x1B($026E, $01)                                     ;B4A514
    %AICMD0x0D($01, $00, $70, $01)                             ;B4A518
    %AICMD0x13_Wait(30)                                        ;B4A51D
    %AICMD0x1C_ShowDialog($028F, $00)                          ;B4A520
    %AICMD0x0B_SetScriptFlag($02)                                            ;B4A524
    %AICMD0x1B($026E, $00)                                     ;B4A526
    %AICMD0x0D($FF, $00, $80, $01)                             ;B4A52A
    %AICMD0x37()                                               ;B4A52F
    %AICMD0x10_End()                                           ;B4A530


